  .toast { position: fixed; bottom: 22px; left: 50%; transform: translateX(-50%); background: var(--blue-dark); color: #fff; padding: 12px 22px; border-radius: 999px; font-size: 0.9rem; z-index: 100; opacity: 0; transition: opacity .2s; pointer-events: none; }
  .toast.show { opacity: 1; }
  @media (max-width: 700px) { main { padding: 14px; } header { padding: 14px 16px; } }
</style>
</head>
<body>
<div class="gate" id="gate">
  <div class="gate-box">
    <div class="brand">لوحة تحكم المطوع للسياحة</div>
    <p>لفريق العمل فقط — أدخل كلمة المرور</p>
    <input type="password" id="passcodeInput" placeholder="كلمة المرور">
    <button id="loginBtn">دخول</button>
    <div class="gate-error" id="gateError"></div>
  </div>
</div>
<div id="app">
  <header>
    <div class="brand">✦ لوحة تحكم المطوع للسياحة</div>
    <div class="tabs">
      <button data-tab="bookings" class="active">الحجوزات</button>
      <button data-tab="packages">الباقات</button>
    </div>
    <button class="logout-btn" id="logoutBtn">خروج</button>
  </header>
  <main>
    <div id="bookingsPanel">
      <div class="refresh-row">
        <h2>الحجوزات</h2>
        <button class="refresh-btn" id="refreshBookings">🔄 تحديث</button>
      </div>
      <div class="table-wrap">
        <table id="bookingsTable">
          <thead><tr><th>العميل</th><th>الهاتف</th><th>الباقة</th><th>عدد المسافرين</th><th>حالة الحجز</th><th>حالة الدفع</th><th>ملاحظات</th><th></th></tr></thead>
