  function callApi(payload){
    return fetch(API, { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify(payload) }).then(function(r){ return r.json(); });
  }
  function showLoading(v){ document.getElementById("loadingMsg").style.display = v ? "block" : "none"; }
  function showErr(msg){ var e = document.getElementById("errMsg"); e.style.display = msg ? "block" : "none"; e.textContent = msg || ""; }
  function loadCities(country){
    document.getElementById("countryView").style.display = "none";
