  }
  function cityCardHtml(city, country){
    return '<div class="city-card" data-name="' + escAttr(city.name) + '" data-country="' + escAttr(country) + '"><h4>' + esc(city.name) + '</h4><p>' + esc(city.blurb || '') + '</p></div>';
