      (data.groups || []).forEach(function(g){ (g.cities||[]).forEach(function(c){ all.push(c); }); });
      html += '<div class="city-grid">';
      all.forEach(function(c){ html += cityCardHtml(c, data.country); });
      html += '</div>';
