      (data.landmarks || []).forEach(function(l){
        body += '<div class="landmark-item"><b>' + esc(l.name) + '</b><span>' + esc(l.description || '') + '</span></div>';
      });
      document.getElementById("modalBody").innerHTML = body;
    }).catch(function(){ document.getElementById("modalBody").innerHTML = '<div class="err-msg">صار خطأ بالاتصال</div>'; });
  }
  document.getElementById("modalClose").addEventListener("click", function(){ document.getElementById("detailModal").classList.remove("open"); });
  document.getElementById("detailModal").addEventListener("click", function(e){ if (e.target === document.getElementById("detailModal")) document.getElementById("detailModal").classList.remove("open"); });
  var searchInput = document.getElementById("searchInput");
  var searchResults = document.getElementById("searchResults");
  var searchTimer = null;
  searchInput.addEventListener("input", function(){
    var q = searchInput.value.trim();
    clearTimeout(searchTimer);
    if (!q) { searchResults.classList.remove("show"); return; }
    searchTimer = setTimeout(function(){
      callApi({ action:"search", query: q }).then(function(data){
        if (!data || !data.success || !data.results || !data.results.length) { searchResults.classList.remove("show"); return; }
        searchResults.innerHTML = data.results.map(function(r){
