const bookings = $("Get Bookings").all();
const customers = $("Get All Customers").all();
const packages = $("Get All Packages").all();
const custMap = {}; customers.forEach(function(c){ custMap[c.json.id] = c.json.fields; });
const pkgMap = {}; packages.forEach(function(p){ pkgMap[p.json.id] = p.json.fields; });
const rows = bookings.map(function(b){
  const f = b.json.fields;
  const custId = (f["Customer"] || [])[0];
  const pkgId = (f["Package"] || [])[0];
  const cust = custMap[custId] || {};
  const pkg = pkgMap[pkgId] || {};
  return {
    id: b.json.id,
    customerName: cust["Full Name"] || "",
    customerPhone: cust["Phone"] || "",
    packageTitle: pkg["Title"] || "",
    travelers: f["Number of Travelers"] || 0,
    bookingStatus: f["Booking Status"] || "",
    paymentStatus: f["Payment Status"] || "",
    notes: f["Special Requests"] || "",
    createdTime: b.json.createdTime
  };
});
rows.sort(function(a,b){ return new Date(b.createdTime) - new Date(a.createdTime); });
return [{ json: { success: true, bookings: rows } }];

