  function openDateRangePicker(){
    var today = new Date(); today.setHours(0,0,0,0);
    var todayISO = toISO(today.getFullYear(), today.getMonth(), today.getDate());
    var state = { start: hpDate1.dataset.iso || null, end: hpDate2.dataset.iso || null };
    var mode = state.start ? 'end' : 'start';
    var overlay = document.createElement('div');
    overlay.className = 'cal-overlay';
    overlay.innerHTML = '<div class="cal-inner"><div class="cal-head"><button type="button" class="dest-close">\u2715</button><span class="cal-title" id="calTitle"></span></div><div class="cal-scroll" id="calScroll"></div><div class="cal-done-bar"><button type="button" class="hp-search-btn" id="calDoneBtn" disabled>\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u062a\u0648\u0627\u0631\u064a\u062e</button></div></div>';
    document.body.appendChild(overlay);
    var titleEl = overlay.querySelector('#calTitle');
    var scrollEl = overlay.querySelector('#calScroll');
    var doneBtn = overlay.querySelector('#calDoneBtn');
    function updateTitle(){ titleEl.textContent = mode === 'start' ? '\u0627\u062e\u062a\u0631 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0630\u0647\u0627\u0628' : '\u0627\u062e\u062a\u0631 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0639\u0648\u062f\u0629'; }
    function buildMonth(y, m){
      var first = new Date(y, m, 1);
      var daysInMonth = new Date(y, m + 1, 0).getDate();
      var startOffset = first.getDay();
      var out = '<div class="cal-month"><div class="cal-month-title">' + ARABIC_MONTHS[m] + ' ' + y + '</div><div class="cal-grid cal-grid-head">';
      for (var w = 0; w < 7; w++) out += '<div class="cal-dow">' + ARABIC_DAYS[w] + '</div>';
      out += '</div><div class="cal-grid">';
      for (var b = 0; b < startOffset; b++) out += '<div class="cal-day cal-blank">.</div>';
      for (var d = 1; d <= daysInMonth; d++) {
        var iso = toISO(y, m, d);
        var floor = mode === 'start' ? todayISO : (state.start || todayISO);
        var disabled = iso < floor;
        var cls = 'cal-day';
        if (disabled) cls += ' disabled';
        if (iso === state.start) cls += ' cal-start';
        if (iso === state.end) cls += ' cal-end';
        if (state.start && state.end && iso > state.start && iso < state.end) cls += ' cal-in-range';
        out += '<div class="' + cls + '" data-iso="' + iso + '">' + d + '</div>';
      }
      out += '</div></div>';
      return out;
    }
    function render(){
      updateTitle();
      var html2 = '';
      for (var i = 0; i < 5; i++) {
        var mm = today.getMonth() + i;
        var yy = today.getFullYear() + Math.floor(mm / 12);
        var actualM = ((mm % 12) + 12) % 12;
        html2 += buildMonth(yy, actualM);
      }
      scrollEl.innerHTML = html2;
      scrollEl.querySelectorAll('.cal-day:not(.disabled):not(.cal-blank)').forEach(function(el){
        el.addEventListener('click', function(){
          var iso = el.getAttribute('data-iso');
          if (mode === 'start') { state.start = iso; state.end = null; mode = 'end'; }
          else if (iso < state.start) { state.start = iso; state.end = null; }
          else { state.end = iso; mode = 'start'; }
          doneBtn.disabled = !(state.start && state.end);
          render();
        });
      });
    }
    render();
    overlay.querySelector('.dest-close').addEventListener('click', function(){ document.body.removeChild(overlay); });
    doneBtn.addEventListener('click', function(){
      if (!state.start || !state.end) return;
      hpDate1.dataset.iso = state.start; hpDate1.value = formatDisp(state.start);
      hpDate2.dataset.iso = state.end; hpDate2.value = formatDisp(state.end);
      document.body.removeChild(overlay);
    });
  }
