</div>
<script>
(function(){
  var API = "https://n8n-production-47b1.up.railway.app/webhook/explore-api";
  var countries = [
    {name:"البحرين",flag:"🇧🇭"},{name:"السعودية",flag:"🇸🇦"},{name:"الإمارات",flag:"🇦🇪"},
    {name:"عمان",flag:"🇴🇲"},{name:"العراق",flag:"🇮🇶"},{name:"سوريا",flag:"🇸🇾"},
    {name:"الأردن",flag:"🇯🇴"},{name:"تركيا",flag:"🇹🇷"},{name:"جورجيا",flag:"🇬🇪"},
    {name:"أرمينيا",flag:"🇦🇲"},{name:"أذربيجان",flag:"🇦🇿"},{name:"مصر",flag:"🇪🇬"}
  ];
  var countryGrid = document.getElementById("countryGrid");
  countries.forEach(function(c){
    var div = document.createElement("div");
    div.className = "country-card";
    div.innerHTML = '<div class="flag">' + c.flag + '</div><div class="name">' + c.name + '</div>';
    div.addEventListener("click", function(){ loadCities(c.name); });
    countryGrid.appendChild(div);
  });
  function callApi(payload){
    return fetch(API, { method:"POST", headers:{"Content-Type":"application/json"}, body: JSON.stringify(payload) }).then(function(r){ return r.json(); });
  }
  function showLoading(v){ document.getElementById("loadingMsg").style.display = v ? "block" : "none"; }
  function showErr(msg){ var e = document.getElementById("errMsg"); e.style.display = msg ? "block" : "none"; e.textContent = msg || ""; }
  function loadCities(country){
    document.getElementById("countryView").style.display = "none";
    document.getElementById("citiesView").style.display = "block";
    document.getElementById("breadcrumb").style.display = "block";
    document.getElementById("bcCountry").textContent = " / " + country;
    document.getElementById("citiesView").innerHTML = "";
    showErr(""); showLoading(true);
    callApi({ action:"listCities", country: country }).then(function(data){
      showLoading(false);
      if (!data || !data.success) { showErr("تعذر تحميل المدن، حاول مرة ثانية"); return; }
      renderCities(data);
    }).catch(function(){ showLoading(false); showErr("صار خطأ بالاتصال"); });
  }
  function cityCardHtml(city, country){
    return '<div class="city-card" data-name="' + escAttr(city.name) + '" data-country="' + escAttr(country) + '"><h4>' + esc(city.name) + '</h4><p>' + esc(city.blurb || '') + '</p></div>';
  }
  function renderCities(data){
    var wrap = document.getElementById("citiesView");
    var html = '';
    if (data.grouped && Array.isArray(data.groups)) {
      data.groups.forEach(function(g){
        html += '<div class="region-block">';
        if (g.region) html += '<h3>' + esc(g.region) + '</h3>';
        html += '<div class="city-grid">';
        (g.cities || []).forEach(function(c){ html += cityCardHtml(c, data.country); });
        html += '</div></div>';
      });
    } else {
      var all = [];
      (data.groups || []).forEach(function(g){ (g.cities||[]).forEach(function(c){ all.push(c); }); });
      html += '<div class="city-grid">';
      all.forEach(function(c){ html += cityCardHtml(c, data.country); });
      html += '</div>';
    }
    wrap.innerHTML = html;
    wrap.querySelectorAll(".city-card").forEach(function(card){
      card.addEventListener("click", function(){ openDetail(card.getAttribute("data-name"), card.getAttribute("data-country")); });
    });
  }
  document.getElementById("backHome").addEventListener("click", function(){
    document.getElementById("countryView").style.display = "block";
    document.getElementById("citiesView").style.display = "none";
    document.getElementById("breadcrumb").style.display = "none";
  });
  function openDetail(name, country){
    var modal = document.getElementById("detailModal");
    document.getElementById("modalImgWrap").innerHTML = "";
    document.getElementById("modalBody").innerHTML = '<div style="text-align:center;padding:30px;color:#6b7f7c;">جاري التحميل...</div>';
    modal.classList.add("open");
    callApi({ action:"getDestinationInfo", name: name, country: country || "" }).then(function(data){
      if (!data || !data.success) { document.getElementById("modalBody").innerHTML = '<div class="err-msg">تعذر تحميل التفاصيل</div>'; return; }
      if (data.image_url) document.getElementById("modalImgWrap").innerHTML = '<img src="' + escAttr(data.image_url) + '">';
      var body = '<h3>' + esc(data.title || name) + '</h3>';
      body += '<p class="summary">' + esc(data.summary || '') + '</p>';
      (data.landmarks || []).forEach(function(l){
        body += '<div class="landmark-item"><b>' + esc(l.name) + '</b><span>' + esc(l.description || '') + '</span></div>';
      });
      document.getElementById("modalBody").innerHTML = body;
    }).catch(function(){ document.getElementById("modalBody").innerHTML = '<div class="err-msg">صار خطأ بالاتصال</div>'; });
  }
  document.getElementById("modalClose").addEventListener("click", function(){ document.getElementById("detailModal").classList.remove("open"); });
  document.getElementById("detailModal").addEventListener("click", function(e){ if (e.target === document.getElementById("detailModal")) document.getElementById("detailModal").classList.remove("open"); });
  var searchInput = document.getElementById("searchInput");
  var searchResults = document.getElementById("searchResults");
  var searchTimer = null;
  searchInput.addEventListener("input", function(){
    var q = searchInput.value.trim();
    clearTimeout(searchTimer);
    if (!q) { searchResults.classList.remove("show"); return; }
    searchTimer = setTimeout(function(){
      callApi({ action:"search", query: q }).then(function(data){
        if (!data || !data.success || !data.results || !data.results.length) { searchResults.classList.remove("show"); return; }
        searchResults.innerHTML = data.results.map(function(r){
          return '<div class="sr-item" data-name="' + escAttr(r.title) + '"><b>' + esc(r.title) + '</b><span>' + esc(r.snippet || '') + '</span></div>';
        }).join('');
        searchResults.classList.add("show");
        searchResults.querySelectorAll(".sr-item").forEach(function(item){
          item.addEventListener("click", function(){
            searchResults.classList.remove("show");
            searchInput.value = item.getAttribute("data-name");
            openDetail(item.getAttribute("data-name"), "");
          });
        });
      }).catch(function(){});
    }, 400);
  });
  document.addEventListener("click", function(e){ if (!e.target.closest(".search-wrap")) searchResults.classList.remove("show"); });
  function esc(s){ return String(s == null ? "" : s).replace(/[&<>"']/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
  function escAttr(s){ return esc(s).replace(/\`/g, "&#96;"); }
})();
</script>
</body>
</html>`;
